const EVENTS = [
  { y: 1850, mo: 11, t: '奥尔米茨之辱', p: '奥尔米茨', m: '今捷克奥洛莫乌茨', ll: [17.25, 49.59], k: 'dip', refs: ['后世文献'],
    d: '1848 年革命失败后，普鲁士国王腓特烈·威廉四世想在普鲁士的领导下建立不包括奥地利的德意志诸侯联盟。奥地利在俄罗斯的支持下恢复了德意志邦联，两国为黑森选侯国的内乱险些开战。十一月二十九日，普鲁士在奥尔米茨签约让步，放弃联盟计划，普鲁士人称之为“奥尔米茨之辱”。',
    who: ['腓特烈·威廉四世', '弗朗茨·约瑟夫', '尼古拉一世'] },
  { y: 1851, mo: 3, t: '威尔第的《弄臣》', p: '威尼斯', m: '今意大利威尼托大区', ll: [12.33, 45.44], k: 'cul', refs: ['后世文献'],
    d: '三月十一日，朱塞佩·威尔第的歌剧《弄臣》在威尼斯的凤凰剧院首演，剧本改编自雨果被禁演的剧作《国王寻乐》，为通过奥地利的审查，把法国国王改成了曼托瓦公爵。两年后他又写出《游吟诗人》与《茶花女》。',
    who: ['朱塞佩·威尔第', '维克多·雨果'] },
  { y: 1851, mo: 5, t: '水晶宫博览会', p: '伦敦', m: '今英国首都', ll: [-0.17, 51.5], k: 'eco', refs: ['后世文献'],
    d: '五月一日，维多利亚女王在海德公园主持万国工业博览会开幕，展馆由园艺师约瑟夫·帕克斯顿设计，用铁架与三十万块玻璃拼成，被称为“水晶宫”。博览会由女王的丈夫阿尔伯特亲王主持筹办，展出各国的机器与工艺品十万多件，半年内有六百多万人次参观。',
    who: ['维多利亚女王'] },
  { y: 1851, mo: 12, t: '十二月二日政变', p: '巴黎', m: '今法国首都', ll: [2.35, 48.86], k: 'pol', refs: ['后世文献'],
    d: '宪法规定总统不能连任，议会又拒绝修宪。十二月二日，奥斯特里茨之战纪念日，总统路易—拿破仑·波拿巴发动政变，解散议会，逮捕反对派议员，镇压巴黎与外省的抵抗，随后以公民投票批准延长总统任期十年。雨果流亡海外，在泽西与根西岛住了将近二十年。',
    who: ['路易—拿破仑·波拿巴', '维克多·雨果'] },
  { y: 1852, mo: 1, t: '埃米尔·卡比尔被杀', p: '卡尚', m: '今伊朗伊斯法罕省', ll: [51.44, 33.98], k: 'pol', refs: ['后世文献'],
    d: '伊朗首相埃米尔·卡比尔整顿财政与军队，创办了德黑兰的综合技术学院，限制宫廷与贵族的特权，招致太后与权贵的忌恨。年轻的纳赛尔丁沙罢免并流放了他，一月，他在卡尚的芬园浴室中被割腕处死。',
    who: ['纳赛尔丁沙'] },
  { y: 1852, mo: 3, t: '《汤姆叔叔的小屋》', p: '波士顿', m: '今美国马萨诸塞州', ll: [-71.06, 42.36], k: 'cul', refs: ['后世文献'],
    d: '三月，哈丽雅特·比彻·斯托的小说《汤姆叔叔的小屋》在报刊连载后出版单行本，描写黑奴汤姆被转卖、受虐而死的一生，第一年在美国就卖出三十万册，在英国卖出一百万册以上，使北方的废奴情绪大为高涨，南方则斥之为诽谤。',
    who: ['哈丽雅特·比彻·斯托'] },
  { y: 1852, mo: 11, t: '加富尔出任首相', p: '都灵', m: '今意大利皮埃蒙特大区', ll: [7.68, 45.07], k: 'pol', refs: ['后世文献'],
    d: '十一月，卡米洛·奔索·迪·加富尔伯爵出任撒丁王国首相。他在英法游历过，崇尚议会政治与自由贸易，主持修建铁路、改革财政，削减修会的特权，又与中间派联合，组成稳定的议会多数，把撒丁变成意大利最先进的邦国。',
    who: ['卡米洛·加富尔', '维托里奥·埃马努埃莱二世'] },
  { y: 1852, mo: 12, t: '第二帝国', p: '巴黎', m: '今法国首都', ll: [2.33, 48.86], k: 'pol', refs: ['后世文献'],
    d: '十一月的公民投票以七百八十万票对二十五万票赞成恢复帝制。十二月二日，路易—拿破仑·波拿巴称“法兰西人的皇帝拿破仑三世”，建立第二帝国。次年一月他与西班牙贵族欧仁妮·德·蒙蒂若结婚。',
    who: ['路易—拿破仑·波拿巴'] },
  { y: 1853, mo: 6, t: '奥斯曼改造巴黎', p: '巴黎', m: '今法国首都', ll: [2.34, 48.87], k: 'eco', refs: ['后世文献'],
    d: '六月，拿破仑三世任命乔治—欧仁·奥斯曼为塞纳省省长，主持改造巴黎。此后十七年间，中世纪的狭窄街巷被大量拆除，开辟了笔直宽阔的林荫大道，修建了下水道、供水系统、公园与统一立面的公寓楼，巴黎的面貌由此奠定。',
    who: ['路易—拿破仑·波拿巴', '乔治—欧仁·奥斯曼'] },
  { y: 1853, mo: 10, t: '克里米亚战争爆发', p: '锡诺普', m: '今土耳其锡诺普省', ll: [35.15, 42.03], k: 'war', refs: ['后世文献'],
    d: '俄罗斯要求保护奥斯曼境内的东正教徒，七月出兵占领摩尔达维亚与瓦拉几亚。十月四日，苏丹阿卜杜勒迈吉德一世对俄宣战。十一月三十日，俄国舰队在锡诺普港用开花弹全歼奥斯曼舰队。次年三月，英国与法兰西对俄宣战。',
    who: ['尼古拉一世', '阿卜杜勒迈吉德一世', '路易—拿破仑·波拿巴'] },
  { y: 1854, mo: 10, t: '轻骑兵冲锋', p: '巴拉克拉瓦', m: '今克里米亚塞瓦斯托波尔', ll: [33.6, 44.5], k: 'war', refs: ['后世文献'],
    d: '九月，英法联军在克里米亚登陆，在阿尔马河击败俄军，随即围攻塞瓦斯托波尔。十月二十五日的巴拉克拉瓦之战中，英军轻骑兵旅因命令传达失误，冲进三面布有俄军炮兵的山谷，六百多人中伤亡与被俘的将近一半。桂冠诗人丁尼生为此写了《轻骑兵冲锋》。',
    who: ['阿尔弗雷德·丁尼生'] },
  { y: 1854, mo: 11, t: '南丁格尔到斯库塔里', p: '斯库塔里', m: '今土耳其伊斯坦布尔于斯屈达尔', ll: [29.02, 41.02], k: 'cul', refs: ['后世文献'],
    d: '《泰晤士报》的战地记者报道了英军伤病员无人照料的惨状。十一月，弗洛伦丝·南丁格尔带领三十八名护士来到斯库塔里的英军医院，整顿卫生、伙食与洗衣，夜间提灯巡视病房，被称为“提灯女士”。她后来用统计图表说明士兵多死于可以预防的疾病。',
    who: ['弗洛伦丝·南丁格尔'] },
  { y: 1855, mo: 3, t: '尼古拉一世去世', p: '圣彼得堡', m: '今俄罗斯圣彼得堡', ll: [30.32, 59.94], k: 'pol', refs: ['后世文献'],
    d: '三月二日，尼古拉一世在战争失利中病逝，长子沙皇亚历山大二世即位。年初撒丁王国在加富尔的主持下加入英法一方，派一万八千人前往克里米亚，以便在和会上取得发言权。',
    who: ['尼古拉一世', '沙皇亚历山大二世', '卡米洛·加富尔'] },
  { y: 1855, mo: 9, t: '塞瓦斯托波尔陷落', p: '塞瓦斯托波尔', m: '今克里米亚塞瓦斯托波尔', ll: [33.52, 44.6], k: 'war', refs: ['后世文献'],
    d: '围城持续将近一年。九月八日，法军攻下马拉科夫棱堡，俄军当夜炸毁工事，撤出塞瓦斯托波尔南城。青年炮兵军官列夫·托尔斯泰亲历了围城，写下《塞瓦斯托波尔故事》。战争中双方死亡数十万人，大多死于霍乱、痢疾等疾病。',
    who: ['列夫·托尔斯泰'] },
  { y: 1856, mo: 3, t: '巴黎和约', p: '巴黎', m: '今法国首都', ll: [2.32, 48.87], k: 'dip', refs: ['后世文献'],
    d: '二月，苏丹阿卜杜勒迈吉德一世颁布改革诏书，承诺各宗教的臣民一律平等。三月三十日签订的巴黎和约规定黑海中立，俄罗斯不得在黑海保有舰队与要塞，把比萨拉比亚南部交还摩尔达维亚，列强共同保证奥斯曼帝国的完整，多瑙河两公国改由列强共同保护。',
    who: ['阿卜杜勒迈吉德一世', '沙皇亚历山大二世', '路易—拿破仑·波拿巴'] },
  { y: 1856, mo: 8, t: '尼安德特人', p: '尼安德河谷', m: '今德国北莱茵—威斯特法伦州梅特曼', ll: [6.95, 51.23], k: 'cul', refs: ['后世文献'],
    d: '八月，杜塞尔多夫附近尼安德河谷的采石工人在一个山洞里挖出一具头骨与骨骼，当地教师约翰·卡尔·富尔罗特认出它们与现代人不同。1864 年，这种古人类被命名为尼安德特人，成为最早得到命名的人类化石物种。',
    who: [] },
  { y: 1857, mo: 2, t: '《包法利夫人》与《恶之花》', p: '巴黎', m: '今法国首都', ll: [2.35, 48.85], k: 'cul', refs: ['后世文献'],
    d: '居斯塔夫·福楼拜的小说《包法利夫人》描写外省医生之妻爱玛的婚外恋与破产自杀，连载后被控有伤风化，二月七日法庭判决无罪。六月，夏尔·波德莱尔出版诗集《恶之花》，八月被判有伤风化，删去六首诗并处以罚款。',
    who: ['居斯塔夫·福楼拜', '夏尔·波德莱尔'] },
  { y: 1857, mo: 5, t: '印度大起义', p: '密拉特', m: '今印度北方邦', ll: [77.7, 28.98], k: 'war', refs: ['后世文献'],
    d: '东印度公司的印度兵听说新式步枪的弹药纸用牛油与猪油润滑，宗教情绪激愤。五月十日，密拉特的印度兵杀死英国军官，次日占领德里，拥立年老的莫卧儿皇帝巴哈杜尔·沙二世。起义蔓延到北印度各地，坎普尔与勒克瑙发生激烈的屠杀与围城，英军次年才平定。',
    who: [] },
  { y: 1858, mo: 1, t: '奥尔西尼行刺', p: '巴黎', m: '今法国首都', ll: [2.33, 48.87], k: 'pol', refs: ['后世文献'],
    d: '一月十四日晚，意大利革命者费利切·奥尔西尼在巴黎歌剧院门前向拿破仑三世夫妇的马车投掷炸弹，皇帝夫妇无恙，周围的人死伤一百多人。奥尔西尼在狱中写信请皇帝援助意大利的独立，被处死。',
    who: ['路易—拿破仑·波拿巴'] },
  { y: 1858, mo: 7, t: '普隆比耶尔密约', p: '普隆比耶尔', m: '今法国孚日省', ll: [6.46, 47.96], k: 'dip', refs: ['后世文献'],
    d: '七月二十一日，加富尔在孚日山区的温泉小镇普隆比耶尔秘密会见拿破仑三世，约定奥地利如果进攻撒丁，法兰西就出兵相助，把奥地利逐出意大利，撒丁取得伦巴第与威尼西亚，以萨伏依与尼斯作为报偿。',
    who: ['卡米洛·加富尔', '路易—拿破仑·波拿巴'] },
  { y: 1858, mo: 8, t: '东印度公司的终结', p: '伦敦', m: '今英国首都', ll: [-0.13, 51.5], k: 'pol', refs: ['后世文献'],
    d: '大起义之后，议会在八月二日通过印度政府法，把东印度公司在印度的权力移交英王，设立印度事务大臣，总督兼称副王。十一月一日，维多利亚女王的宣言在印度各地宣读，承诺尊重印度的宗教与王公的权利。巴哈杜尔·沙二世被流放到仰光，莫卧儿王朝终结。',
    who: ['维多利亚女王'] },
  { y: 1859, mo: 2, t: '库扎当选两公国大公', p: '布加勒斯特', m: '今罗马尼亚首都', ll: [26.1, 44.43], k: 'pol', refs: ['后世文献'],
    d: '巴黎会议规定摩尔达维亚与瓦拉几亚各选一位大公。一月十七日摩尔达维亚议会、二月五日瓦拉几亚议会先后选举同一个人——摩尔达维亚的上校亚历山德鲁·约安·库扎，造成事实上的统一，列强后来予以承认。1862 年两公国合并政府，定都布加勒斯特，开始称罗马尼亚。',
    who: ['亚历山德鲁·约安·库扎'] },
  { y: 1859, mo: 2.5, t: '密尔的《论自由》', p: '伦敦', m: '今英国首都', ll: [-0.12, 51.51], k: 'cul', refs: ['论自由'],
    d: '二月，约翰·斯图尔特·密尔出版《论自由》，献给去年去世的妻子哈丽雅特·泰勒。书中主张社会只能为防止伤害他人而干涉个人：“**对于他自己，对于他自己的身体与心灵，个人是主权者。||Over himself, over his own body and mind, the individual is sovereign.**”',
    who: ['约翰·斯图尔特·密尔'] },
  { y: 1859, mo: 4, t: '苏伊士运河动工', p: '塞得港', m: '今埃及塞得港省', ll: [32.3, 31.26], k: 'eco', refs: ['后世文献'],
    d: '法国外交官费迪南·德·雷赛布从埃及总督赛义德手中取得开凿地峡的特许，在巴黎募股成立苏伊士运河公司。四月二十五日，运河在地中海岸的塞得港动工，雇用了大批埃及徭役劳工，英国一再反对。',
    who: ['费迪南·德·雷赛布'] },
  { y: 1859, mo: 4.5, t: '狄更斯的《双城记》', p: '伦敦', m: '今英国首都', ll: [-0.11, 51.51], k: 'cul', refs: ['双城记'],
    d: '四月三十日，狄更斯在自己新创办的周刊上开始连载以法国大革命为背景的《双城记》，开头写道：“**那是最好的时代，那是最坏的时代||It was the best of times, it was the worst of times**”。小说结尾，律师卡尔顿代替相貌相似的达尔奈走上断头台。',
    who: ['查尔斯·狄更斯'] },
  { y: 1859, mo: 5, t: '第二次意大利独立战争', p: '蒙特贝洛', m: '今意大利伦巴第大区帕维亚省', ll: [9.1, 45.0], k: 'war', refs: ['后世文献'],
    d: '加富尔在边境集结志愿军，挑动奥地利。四月下旬奥地利发出最后通牒，随即渡过提契诺河进攻撒丁，法兰西按约参战，拿破仑三世亲自率军进入意大利，五月在蒙特贝洛与帕莱斯特罗获胜。加里波第率阿尔卑斯猎兵在伦巴第北部作战。同月，两西西里的斐迪南二世去世，弗朗切斯科二世即位。',
    who: ['卡米洛·加富尔', '路易—拿破仑·波拿巴', '朱塞佩·加里波第', '弗朗茨·约瑟夫'] },
  { y: 1859, mo: 6, t: '马真塔与索尔费里诺', p: '索尔费里诺', m: '今意大利伦巴第大区曼托瓦省', ll: [10.57, 45.37], k: 'war', refs: ['后世文献'],
    d: '六月四日法军在马真塔击败奥军，八日拿破仑三世与维托里奥·埃马努埃莱二世进入米兰。二十四日，双方三十多万人在索尔费里诺与圣马蒂诺激战，弗朗茨·约瑟夫亲自指挥的奥军败退，双方死伤近四万人。日内瓦商人亨利·杜南路过战场，组织当地妇女救护伤兵。',
    who: ['路易—拿破仑·波拿巴', '维托里奥·埃马努埃莱二世', '弗朗茨·约瑟夫', '亨利·杜南'] },
  { y: 1859, mo: 7, t: '维拉弗兰卡停战', p: '维拉弗兰卡', m: '今意大利威尼托大区维罗纳省', ll: [10.85, 45.35], k: 'dip', refs: ['后世文献'],
    d: '拿破仑三世担心普鲁士出兵莱茵河，又对战场的伤亡感到震惊，七月十一日瞒着撒丁与弗朗茨·约瑟夫在维拉弗兰卡议和：奥地利把伦巴第交给法兰西转让撒丁，保留威尼西亚。加富尔愤而辞职。同月，瑞典国王奥斯卡一世去世，卡尔十五世即位。',
    who: ['路易—拿破仑·波拿巴', '弗朗茨·约瑟夫', '卡米洛·加富尔', '奥斯卡一世'] },
  { y: 1859, mo: 9, t: '沙米勒投降', p: '古尼布', m: '今俄罗斯达吉斯坦共和国', ll: [46.96, 42.4], k: 'war', refs: ['后世文献'],
    d: '阿瓦尔人伊玛目沙米勒领导达吉斯坦与车臣的山民抵抗俄军二十五年。俄军伐林修路、步步推进，九月六日（俄历八月二十五日），巴里亚京斯基公爵在古尼布山村包围了他，沙米勒投降，被送往卡卢加软禁，受到优待。',
    who: ['伊玛目沙米勒', '沙皇亚历山大二世'] },
  { y: 1859, mo: 11, t: '《物种起源》', p: '伦敦', m: '今英国首都', ll: [-0.14, 51.51], k: 'cul', refs: ['物种起源'],
    d: '去年七月，达尔文与阿尔弗雷德·拉塞尔·华莱士关于自然选择的论文在林奈学会同时宣读。十一月二十四日，达尔文出版《物种起源》，首印一千二百五十册当天售罄。全书结尾说：“**生命如此看来是何等壮丽……从如此简单的开端，演化出了无穷无尽、最美丽最奇妙的形态，而且这一演化仍在进行。||There is grandeur in this view of life, with its several powers, having been originally breathed into a few forms or into one; and that, whilst this planet has gone cycling on according to the fixed law of gravity, from so simple a beginning endless forms most beautiful and most wonderful have been, and are being, evolved.**”',
    who: ['查尔斯·达尔文'] },
  { y: 1860, mo: 3, t: '中意大利并入撒丁', p: '佛罗伦萨', m: '今意大利托斯卡纳大区', ll: [11.26, 43.77], k: 'pol', refs: ['后世文献'],
    d: '战争期间，托斯卡纳、帕尔马、摩德纳的君主出逃，教宗国北部的罗马涅也脱离了教宗。一月加富尔复任首相，三月这些地区举行公民投票，以压倒多数赞成并入撒丁王国。教宗庇护九世宣布开除侵占教会领地者的教籍。',
    who: ['卡米洛·加富尔', '教宗庇护九世'] },
  { y: 1860, mo: 4, t: '尼斯与萨伏依归法', p: '尼斯', m: '今法国滨海阿尔卑斯省', ll: [7.27, 43.7], k: 'dip', refs: ['后世文献'],
    d: '作为法兰西同意中意大利并入撒丁的代价，三月二十四日的都灵条约把萨伏依与尼斯割让给法兰西，四月的公民投票几乎全票赞成。生于尼斯的加里波第在议会激烈抗议割让自己的故乡。',
    who: ['朱塞佩·加里波第', '卡米洛·加富尔'] },
  { y: 1860, mo: 5, t: '千人远征', p: '马尔萨拉', m: '今意大利西西里大区特拉帕尼省', ll: [12.44, 37.8], k: 'war', refs: ['后世文献'],
    d: '西西里爆发反对波旁王朝的起义。五月五日夜，加里波第率一千多名志愿者乘两艘汽船从热那亚附近的夸尔托出发，十一日在马尔萨拉登陆，以维托里奥·埃马努埃莱二世的名义自任西西里独裁官，十五日在卡拉塔菲米获胜，月底攻下巴勒莫。他们穿着红衫，被称为“千人团”。',
    who: ['朱塞佩·加里波第', '维托里奥·埃马努埃莱二世'] },
  { y: 1860, mo: 9, t: '加里波第进入那不勒斯', p: '那不勒斯', m: '今意大利坎帕尼亚大区', ll: [14.25, 40.85], k: 'war', refs: ['后世文献'],
    d: '八月加里波第渡过墨西拿海峡，沿卡拉布里亚北上，九月七日进入那不勒斯，弗朗切斯科二世退守加埃塔。加富尔担心加里波第进攻罗马引起法兰西干涉，派撒丁军队穿过教宗国的马尔凯与翁布里亚南下，九月十八日在卡斯特尔菲达尔多击败教宗的军队。十月公民投票后，加里波第在特阿诺把南方交给国王，自己退隐卡普雷拉岛。',
    who: ['朱塞佩·加里波第', '卡米洛·加富尔', '维托里奥·埃马努埃莱二世', '教宗庇护九世'] },
  { y: 1860, mo: 11, t: '林肯当选总统', p: '斯普林菲尔德', m: '今美国伊利诺伊州', ll: [-89.65, 39.8], k: 'pol', refs: ['后世文献'],
    d: '十一月六日，反对奴隶制扩张的共和党候选人亚伯拉罕·林肯当选美国总统，他在南方各州几乎没有得票。十二月二十日南卡罗来纳州宣布脱离联邦，次年二月南方七州成立美利坚联盟国，推举杰斐逊·戴维斯为总统。',
    who: ['亚伯拉罕·林肯'] },
  { y: 1861, mo: 1, t: '威廉一世即位', p: '柏林', m: '今德国首都', ll: [13.4, 52.52], k: 'pol', refs: ['后世文献'],
    d: '腓特烈·威廉四世几次中风，自 1858 年起由弟弟威廉摄政。一月二日国王去世，六十三岁的威廉一世即位，他主张扩充军队，与陆军大臣罗恩改革兵役，延长服役期，遭到议会中自由派多数的反对。',
    who: ['腓特烈·威廉四世', '威廉一世'] },
  { y: 1861, mo: 3, t: '俄国废除农奴制', p: '圣彼得堡', m: '今俄罗斯圣彼得堡', ll: [30.31, 59.94], k: 'pol', refs: ['后世文献'],
    d: '沙皇亚历山大二世在 1856 年对莫斯科的贵族说过，与其等农奴自下而上解放自己，不如自上而下废除农奴制。三月三日（俄历二月十九日），他签署的解放宣言颁布，两千多万地主农奴获得人身自由，但必须以分期赎买的方式取得份地，土地往往比原来耕种的更少。',
    who: ['沙皇亚历山大二世'] },
  { y: 1861, mo: 3.5, t: '意大利王国', p: '都灵', m: '今意大利皮埃蒙特大区', ll: [7.69, 45.07], k: 'pol', refs: ['后世文献'],
    d: '二月加埃塔投降，弗朗切斯科二世流亡罗马。三月十七日，在都灵召开的第一届全国议会宣布维托里奥·埃马努埃莱二世为意大利国王，意大利王国成立，但威尼西亚仍属奥地利，罗马仍由法军保护的教宗统治。',
    who: ['维托里奥·埃马努埃莱二世', '卡米洛·加富尔'] },
  { y: 1861, mo: 4, t: '美国内战爆发', p: '萨姆特堡', m: '今美国南卡罗来纳州查尔斯顿', ll: [-79.87, 32.75], k: 'war', refs: ['后世文献'],
    d: '四月十二日，南方联盟的炮兵轰击查尔斯顿港内联邦军驻守的萨姆特堡，守军次日投降。林肯号召各州出兵七万五千人平叛，弗吉尼亚等四州随即加入南方。七月，两军在马纳萨斯附近的布尔河首次交战，北军溃败。',
    who: ['亚伯拉罕·林肯'] },
  { y: 1861, mo: 6, t: '加富尔去世', p: '都灵', m: '今意大利皮埃蒙特大区', ll: [7.68, 45.06], k: 'pol', refs: ['后世文献'],
    d: '意大利王国成立不到三个月，六月六日加富尔病逝，年仅五十岁。同月二十五日，苏丹阿卜杜勒迈吉德一世病逝，弟弟阿卜杜勒阿齐兹即位。',
    who: ['卡米洛·加富尔', '阿卜杜勒迈吉德一世', '阿卜杜勒阿齐兹'] },
  { y: 1862, mo: 4, t: '雨果的《悲惨世界》', p: '布鲁塞尔', m: '今比利时首都', ll: [4.35, 50.85], k: 'cul', refs: ['后世文献'],
    d: '流亡根西岛的雨果写成长篇小说《悲惨世界》，四月起在布鲁塞尔与巴黎同时分卷出版，写偷面包坐牢十九年的冉阿让出狱后改过向善，被警探沙威追捕的一生，结尾是 1832 年巴黎的共和派起义。',
    who: ['维克多·雨果'] },
  { y: 1862, mo: 9, t: '铁与血', p: '柏林', m: '今德国首都', ll: [13.39, 52.51], k: 'pol', refs: ['后世文献'],
    d: '议会拒绝批准扩军预算，威廉一世一度想退位。九月二十三日，他任命驻巴黎大使奥托·冯·俾斯麦为首相。三十日俾斯麦在议会预算委员会上说，当代的重大问题不是靠演说与多数决议，而是要用铁与血来解决。此后四年他不经议会批准征税扩军。',
    who: ['奥托·冯·俾斯麦', '威廉一世'] },
  { y: 1862, mo: 10, t: '奥托被废', p: '雅典', m: '今希腊首都', ll: [23.73, 37.98], k: 'pol', refs: ['后世文献'],
    d: '巴伐利亚王子出身的希腊国王奥托没有子嗣，统治专断。十月他出巡时，雅典的驻军起事，宣布废黜国王，奥托乘英国军舰返回巴伐利亚。次年希腊国民议会选举丹麦王子威廉为国王，称乔治一世。',
    who: ['希腊国王奥托'] },
  { y: 1863, mo: 1, t: '解放奴隶宣言', p: '华盛顿', m: '今美国首都', ll: [-77.04, 38.9], k: 'pol', refs: ['后世文献'],
    d: '去年九月北军在安蒂特姆挡住了南军的北进，林肯随即发布预告。一月一日，《解放奴隶宣言》生效，宣布叛乱各州的奴隶获得自由，北军开始大量招募黑人士兵。英法因此难以公开支持南方。',
    who: ['亚伯拉罕·林肯', '弗雷德里克·道格拉斯'] },
  { y: 1863, mo: 1.5, t: '波兰一月起义', p: '华沙', m: '今波兰首都', ll: [21.01, 52.23], k: 'war', refs: ['后世文献'],
    d: '俄国当局以强征入伍的办法搜捕激进青年。一月二十二日，波兰与立陶宛的地下组织宣布起义，以游击战对抗俄军一年多，次年春被镇压，数百人被处死，数万人流放西伯利亚。普鲁士与俄国签约协助镇压，俾斯麦由此取得沙皇的好感。',
    who: ['沙皇亚历山大二世', '奥托·冯·俾斯麦'] },
  { y: 1863, mo: 5, t: '落选者沙龙', p: '巴黎', m: '今法国首都', ll: [2.31, 48.87], k: 'cul', refs: ['后世文献'],
    d: '官方沙龙拒收了三千多件作品，引起画家抗议。拿破仑三世下令另设“落选者沙龙”，五月十五日开幕，爱德华·马奈的《草地上的午餐》画了一个裸体女子与两个衣着整齐的男子，引起观众的哄笑与报刊的抨击。',
    who: ['爱德华·马奈', '路易—拿破仑·波拿巴'] },
  { y: 1863, mo: 7, t: '葛底斯堡与维克斯堡', p: '葛底斯堡', m: '今美国宾夕法尼亚州', ll: [-77.23, 39.83], k: 'war', refs: ['后世文献'],
    d: '罗伯特·李率南军第二次北进，七月一日至三日在宾夕法尼亚的葛底斯堡与北军激战，第三天的“皮克特冲锋”失败，双方伤亡五万多人，李撤回弗吉尼亚。七月四日，尤利西斯·格兰特攻下密西西比河上的维克斯堡，南方被一分为二。',
    who: ['罗伯特·李', '尤利西斯·格兰特'] },
  { y: 1863, mo: 11, t: '克里斯蒂安九世即位', p: '哥本哈根', m: '今丹麦首都', ll: [12.57, 55.68], k: 'pol', refs: ['后世文献'],
    d: '十一月十三日，丹麦议会通过把石勒苏益格并入丹麦的新宪法，两天后国王腓特烈七世去世，没有子嗣，格吕克斯堡家族的克里斯蒂安九世即位，签署了新宪法。德意志邦联认为这违背了 1852 年的伦敦议定书。',
    who: ['克里斯蒂安九世'] },
  { y: 1863, mo: 11.5, t: '葛底斯堡演说', p: '葛底斯堡', m: '今美国宾夕法尼亚州', ll: [-77.23, 39.82], k: 'cul', refs: ['葛底斯堡演说'],
    d: '十一月十九日，葛底斯堡的国家公墓落成，林肯在仪式上作了不到三分钟的演说，开头说：“**八十七年前，我们的先辈在这片大陆上创建了一个新的国家，它孕育于自由，奉行人人生而平等的原则。||Four score and seven years ago, our fathers brought forth upon this continent a new nation: conceived in liberty, and dedicated to the proposition that all men are created equal.**”',
    who: ['亚伯拉罕·林肯'] },
  { y: 1864, mo: 4, t: '巴斯德与自然发生说', p: '巴黎', m: '今法国首都', ll: [2.34, 48.85], k: 'cul', refs: ['后世文献'],
    d: '化学家路易·巴斯德研究发酵，证明发酵与腐败是微生物所致。他用弯曲的鹅颈瓶做实验，证明煮沸后的肉汤只要不接触空气中的尘埃就不会腐败。四月七日，他在索邦大学的晚间讲座上宣布自然发生说已被驳倒。他发明的低温加热灭菌法后来称为巴氏消毒法。',
    who: ['路易·巴斯德'] },
  { y: 1864, mo: 4.5, t: '迪伯尔之战', p: '迪伯尔', m: '今丹麦南丹麦大区', ll: [9.73, 54.91], k: 'war', refs: ['后世文献'],
    d: '二月一日，普鲁士与奥地利的军队越过艾德河，进攻丹麦。四月十八日，普军猛攻迪伯尔的堡垒，丹麦军队战败撤退。英国与法兰西没有出兵援助，伦敦会议也没有达成妥协。',
    who: ['奥托·冯·俾斯麦', '克里斯蒂安九世', '威廉一世'] },
  { y: 1864, mo: 5, t: '切尔克斯人的流亡', p: '索契', m: '今俄罗斯克拉斯诺达尔边疆区', ll: [39.73, 43.6], k: 'war', refs: ['后世文献'],
    d: '俄军征服了高加索西北的切尔克斯人地区。五月二十一日，俄军在克巴阿达举行阅兵庆祝战争结束。数十万切尔克斯人与其他山民被驱逐或被迫迁往奥斯曼帝国，途中大批死于饥饿与疾病。',
    who: ['沙皇亚历山大二世'] },
  { y: 1864, mo: 6, t: '伊奥尼亚群岛归希腊', p: '科孚', m: '今希腊伊奥尼亚群岛大区', ll: [19.92, 39.62], k: 'dip', refs: ['后世文献'],
    d: '伊奥尼亚群岛自 1815 年起由英国保护。为表示对新国王的支持，英国把群岛让给希腊，六月二日（希腊旧历五月二十一日），科孚等七岛正式并入希腊王国。',
    who: ['希腊国王乔治一世'] },
  { y: 1864, mo: 8, t: '日内瓦公约', p: '日内瓦', m: '今瑞士日内瓦', ll: [6.15, 46.2], k: 'dip', refs: ['后世文献'],
    d: '亨利·杜南出版《索尔费里诺回忆》，呼吁各国成立中立的救护组织。去年二月，日内瓦的五人委员会成立，后来称为红十字国际委员会。八月二十二日，十二国在日内瓦签订公约，规定战地的伤员与救护人员受到保护，以白底红十字为标志。',
    who: ['亨利·杜南'] },
  { y: 1864, mo: 9, t: '第一国际', p: '伦敦', m: '今英国首都', ll: [-0.13, 51.52], k: 'pol', refs: ['后世文献'],
    d: '九月二十八日，英、法、德、意等国的工人代表在伦敦的圣马丁堂集会，成立国际工人协会，后称第一国际。马克思起草了协会的成立宣言与章程，后来协会内部与巴枯宁派发生分裂。',
    who: ['卡尔·马克思'] },
  { y: 1864, mo: 10, t: '维也纳和约', p: '维也纳', m: '今奥地利首都', ll: [16.37, 48.21], k: 'dip', refs: ['后世文献'],
    d: '十月三十日签订的维也纳和约中，丹麦把石勒苏益格、荷尔斯泰因与劳恩堡三公国交给普鲁士与奥地利共管。次年的加施泰因协定规定石勒苏益格由普鲁士管理，荷尔斯泰因由奥地利管理，两国的矛盾日益尖锐。',
    who: ['奥托·冯·俾斯麦', '弗朗茨·约瑟夫', '克里斯蒂安九世'] },
  { y: 1865, mo: 2, t: '孟德尔的豌豆杂交实验', p: '布尔诺', m: '今捷克南摩拉维亚州', ll: [16.61, 49.19], k: 'cul', refs: ['后世文献'],
    d: '布尔诺奥古斯丁修道院的修士格雷戈尔·孟德尔在修道院的园地里种植豌豆，八年间进行了大量杂交实验，统计各代性状的比例。二月八日与三月八日，他在布尔诺自然科学学会上报告了结果，次年发表，提出了遗传因子分离与自由组合的规律，当时几乎无人注意。',
    who: ['格雷戈尔·孟德尔'] },
  { y: 1865, mo: 4, t: '阿波马托克斯与林肯遇刺', p: '华盛顿', m: '今美国首都', ll: [-77.03, 38.9], k: 'war', refs: ['后世文献'],
    d: '谢尔曼的北军横扫佐治亚与南卡罗来纳，格兰特围困彼得斯堡与里士满。四月九日，罗伯特·李在弗吉尼亚的阿波马托克斯法院投降。十四日晚，林肯在福特剧院看戏时被演员约翰·威尔克斯·布斯开枪击中，次日去世。内战中死亡约六十多万人。年底，废除奴隶制的宪法第十三修正案生效。',
    who: ['亚伯拉罕·林肯', '罗伯特·李', '尤利西斯·格兰特'] },
  { y: 1865, mo: 6, t: '《特里斯坦与伊索尔德》', p: '慕尼黑', m: '今德国巴伐利亚州', ll: [11.58, 48.14], k: 'cul', refs: ['后世文献'],
    d: '理查德·瓦格纳因参加 1849 年德累斯顿起义长年流亡，年轻的巴伐利亚国王路德维希二世崇拜他，替他还清债务，请他到慕尼黑。六月十日，他的乐剧《特里斯坦与伊索尔德》在慕尼黑宫廷剧院首演，开头的“特里斯坦和弦”突破了传统和声。',
    who: ['理查德·瓦格纳'] },
  { y: 1865, mo: 6.5, t: '俄军攻下塔什干', p: '塔什干', m: '今乌兹别克斯坦首都', ll: [69.24, 41.3], k: 'war', refs: ['后世文献'],
    d: '俄罗斯在中亚向南推进，从浩罕汗国手中夺取锡尔河沿岸的要塞。六月，切尔尼亚耶夫将军违抗命令，率不到两千人攻下有十万人口的塔什干城，次年塔什干并入俄罗斯，成为突厥斯坦总督区的首府。',
    who: ['沙皇亚历山大二世'] },
  { y: 1865, mo: 11, t: '《爱丽丝漫游奇境》', p: '牛津', m: '今英国牛津郡', ll: [-1.25, 51.75], k: 'cul', refs: ['爱丽丝漫游奇境'],
    d: '牛津基督堂学院的数学讲师查尔斯·道奇森在泰晤士河上划船游玩时给院长的女儿爱丽丝·利德尔讲故事，后来写成书，以刘易斯·卡罗尔的笔名出版。书中的爱丽丝掉进兔子洞，吃了蛋糕后身子变高，叫道：“**越来越奇怪了！||Curiouser and curiouser!**”',
    who: ['刘易斯·卡罗尔'] },
  { y: 1865, mo: 12, t: '利奥波德二世即位', p: '布鲁塞尔', m: '今比利时首都', ll: [4.36, 50.84], k: 'pol', refs: ['后世文献'],
    d: '十二月十日，比利时开国国王利奥波德一世去世，长子比利时的利奥波德二世即位。他热衷于海外扩张，后来以私人名义取得了刚果盆地的大片土地。',
    who: ['比利时的利奥波德一世', '比利时的利奥波德二世'] },
  { y: 1866, mo: 1, t: '《罪与罚》', p: '圣彼得堡', m: '今俄罗斯圣彼得堡', ll: [30.3, 59.93], k: 'cul', refs: ['罪与罚'],
    d: '陀思妥耶夫斯基因参加彼得拉舍夫斯基小组被判死刑，临刑前改判苦役。一月起他的小说《罪与罚》在《俄罗斯导报》连载，写穷大学生拉斯柯尔尼科夫杀死放高利贷的老太婆后的内心煎熬。书中的主人公说：“**痛苦与磨难，对于博大的智慧与深沉的心灵总是不可避免的。||Pain and suffering are always inevitable for a large intelligence and a deep heart.**”',
    who: ['费奥多尔·陀思妥耶夫斯基'] },
  { y: 1866, mo: 5, t: '卡罗尔一世', p: '布加勒斯特', m: '今罗马尼亚首都', ll: [26.1, 44.44], k: 'pol', refs: ['后世文献'],
    d: '库扎推行土地改革与没收修道院地产，统治日益专断，二月被军官与政客逼迫退位。议会改请德意志的霍亨索伦—西格马林根亲王卡尔为大公，他化装潜行到罗马尼亚，五月二十二日在布加勒斯特宣誓即位，称卡罗尔一世。',
    who: ['亚历山德鲁·约安·库扎', '卡罗尔一世'] },
  { y: 1866, mo: 7, t: '克尼格雷茨之战', p: '克尼格雷茨', m: '今捷克赫拉德茨—克拉洛韦', ll: [15.83, 50.21], k: 'war', refs: ['后世文献'],
    d: '俾斯麦与意大利结盟，又提议改组德意志邦联。六月中旬奥地利与德意志邦联的多数邦国对普鲁士开战。普军总参谋长毛奇利用铁路与电报分三路进入波希米亚，七月三日在克尼格雷茨击溃奥军。在意大利，奥军在库斯托扎与利萨海战中击败了意军。',
    who: ['奥托·冯·俾斯麦', '赫尔穆特·冯·毛奇', '威廉一世', '弗朗茨·约瑟夫'] },
  { y: 1866, mo: 7.5, t: '大西洋电缆', p: '哈茨康滕特', m: '今加拿大纽芬兰与拉布拉多省', ll: [-53.21, 47.84], k: 'eco', refs: ['后世文献'],
    d: '1858 年铺设的第一条大西洋海底电缆只用了几个星期就失效了。巨轮“大东方号”从爱尔兰的瓦伦西亚岛出发铺设新电缆，七月二十七日在纽芬兰登岸，欧洲与北美之间的电报从此畅通，消息几分钟就能越过大洋。',
    who: [] },
  { y: 1866, mo: 8, t: '布拉格和约', p: '布拉格', m: '今捷克首都', ll: [14.42, 50.09], k: 'dip', refs: ['后世文献'],
    d: '俾斯麦说服威廉一世不进军维也纳，对奥地利从宽议和。八月二十三日的布拉格和约中，德意志邦联解散，奥地利退出德意志事务。普鲁士吞并汉诺威、黑森选侯国、拿骚、法兰克福与石勒苏益格—荷尔斯泰因，美因河以南的巴伐利亚、符腾堡、巴登等南德诸邦保持独立，但与普鲁士签订了秘密的攻守同盟。',
    who: ['奥托·冯·俾斯麦', '威廉一世', '弗朗茨·约瑟夫'] },
  { y: 1866, mo: 10, t: '威尼西亚并入意大利', p: '威尼斯', m: '今意大利威尼托大区', ll: [12.34, 45.44], k: 'pol', refs: ['后世文献'],
    d: '奥地利把威尼西亚交给拿破仑三世，再由他转交意大利。十月二十一日的公民投票以压倒多数赞成并入意大利王国，十一月维托里奥·埃马努埃莱二世进入威尼斯。',
    who: ['维托里奥·埃马努埃莱二世', '路易—拿破仑·波拿巴'] },
  { y: 1867, mo: 4, t: '北德意志邦联', p: '柏林', m: '今德国首都', ll: [13.38, 52.51], k: 'pol', refs: ['后世文献'],
    d: '美因河以北的二十多个邦组成北德意志邦联，普鲁士国王任邦联主席，俾斯麦任邦联首相。四月十六日，按男子普选产生的制宪议会通过邦联宪法，七月一日生效。去年九月，普鲁士议会已通过法案，追认了俾斯麦几年来未经批准的开支。',
    who: ['奥托·冯·俾斯麦', '威廉一世'] },
  { y: 1867, mo: 5, t: '诺贝尔的炸药', p: '斯德哥尔摩', m: '今瑞典首都', ll: [18.07, 59.33], k: 'eco', refs: ['后世文献'],
    d: '瑞典化学家阿尔弗雷德·诺贝尔试制硝化甘油炸药，1864 年工厂爆炸，炸死了他的弟弟。他发现用硅藻土吸收硝化甘油可以安全搬运，命名为“达纳炸药”，五月在英国取得专利，随后又在瑞典、美国等国取得专利，广泛用于开矿、修路与开凿隧道。',
    who: ['阿尔弗雷德·诺贝尔'] },
  { y: 1867, mo: 6, t: '奥匈妥协', p: '布达', m: '今匈牙利布达佩斯', ll: [19.04, 47.5], k: 'pol', refs: ['后世文献'],
    d: '战败后的奥地利与匈牙利的自由派领袖戴阿克·费伦茨达成妥协：帝国分为奥地利与匈牙利两半，各有议会与政府，共用君主、外交、军队与相关财政，称奥匈帝国。安德拉希·久洛任匈牙利首相，六月八日，弗朗茨·约瑟夫在布达加冕为匈牙利国王。特兰西瓦尼亚并入匈牙利。同月，拿破仑三世扶植的墨西哥皇帝马克西米利安被墨西哥共和派处决。',
    who: ['弗朗茨·约瑟夫', '戴阿克·费伦茨', '安德拉希·久洛'] },
  { y: 1867, mo: 9, t: '《资本论》', p: '汉堡', m: '今德国汉堡', ll: [9.99, 53.55], k: 'cul', refs: ['后世文献'],
    d: '流亡伦敦的马克思多年在大英博物馆的阅览室研究政治经济学，靠恩格斯的接济生活。九月十四日，《资本论》第一卷在汉堡出版，分析商品、货币、剩余价值与资本积累，后两卷在他死后由恩格斯整理出版。',
    who: ['卡尔·马克思', '弗里德里希·恩格斯'] },
  { y: 1868, mo: 5, t: '撒马尔罕', p: '撒马尔罕', m: '今乌兹别克斯坦撒马尔罕州', ll: [66.97, 39.65], k: 'war', refs: ['后世文献'],
    d: '五月，考夫曼将军率俄军攻下帖木儿的故都撒马尔罕。六月签订的和约中，布哈拉埃米尔割让撒马尔罕与泽拉夫尚河上游，赔款，承认俄罗斯的保护。',
    who: ['沙皇亚历山大二世'] },
  { y: 1868, mo: 9, t: '西班牙光荣革命', p: '加的斯', m: '今西班牙安达卢西亚自治区', ll: [-6.29, 36.53], k: 'pol', refs: ['后世文献'],
    d: '九月十八日，海军在加的斯起事，普里姆与塞拉诺等将军响应，二十八日在阿尔科莱亚桥击败王军，伊莎贝拉二世流亡法兰西。临时政府颁布普选、出版与信仰自由，次年的宪法规定实行君主立宪，由塞拉诺摄政，同时在欧洲各王室中寻找新国王。',
    who: ['伊莎贝拉二世', '胡安·普里姆'] },
  { y: 1868, mo: 12, t: '格莱斯顿与迪斯雷利', p: '伦敦', m: '今英国首都', ll: [-0.13, 51.5], k: 'pol', refs: ['后世文献'],
    d: '去年保守党的本杰明·迪斯雷利推动第二次议会改革法，使城镇工人多数获得选举权。他二月出任首相，但在十一月的大选中失败，十二月自由党领袖威廉·格莱斯顿组阁，着手解决爱尔兰问题，废除爱尔兰圣公会的国教地位。此后两人轮流执政，针锋相对。',
    who: ['本杰明·迪斯雷利', '威廉·格莱斯顿', '维多利亚女王'] },
  { y: 1869, mo: 3, t: '元素周期表', p: '圣彼得堡', m: '今俄罗斯圣彼得堡', ll: [30.3, 59.94], k: 'cul', refs: ['后世文献'],
    d: '圣彼得堡大学的化学教授德米特里·门捷列夫为编写教科书，把已知的六十多种元素按原子量排列，发现性质周期性地重复。三月，他的论文在俄罗斯化学学会上宣读。他在表中留下空位，预言了尚未发现的元素，后来的镓、钪、锗证实了他的预言。',
    who: ['德米特里·门捷列夫'] },
  { y: 1869, mo: 5, t: '横贯大陆铁路', p: '普罗蒙特里峰', m: '今美国犹他州', ll: [-112.55, 41.62], k: 'eco', refs: ['后世文献'],
    d: '中央太平洋铁路从加利福尼亚向东修，大量雇用华工，联合太平洋铁路从内布拉斯加向西修，雇用了许多爱尔兰移民与退伍军人。五月十日，两条铁路在犹他的普罗蒙特里峰接轨，钉下金色的道钉，从纽约到旧金山的旅程从几个月缩短到一个星期左右。',
    who: [] },
  { y: 1869, mo: 11, t: '苏伊士运河通航', p: '伊斯梅利亚', m: '今埃及伊斯梅利亚省', ll: [32.27, 30.6], k: 'eco', refs: ['后世文献'],
    d: '经过十年施工，苏伊士运河完工。十一月十七日，埃及赫迪夫伊斯梅尔举行盛大的通航典礼，欧仁妮皇后乘坐的法国御用游艇“鹰号”率领船队驶入运河。从欧洲到印度的航程比绕道好望角缩短了数千公里。',
    who: ['伊斯梅尔帕夏', '费迪南·德·雷赛布'] },
  { y: 1869, mo: 12, t: '梵蒂冈公会议', p: '罗马', m: '今梵蒂冈', ll: [12.45, 41.9], k: 'cul', refs: ['后世文献'],
    d: '十二月八日，教宗庇护九世召开的梵蒂冈公会议开幕，七百多名主教出席。次年七月十八日，会议通过“教宗无误”的信条：教宗以宗座权威就信仰与道德作出的定断，不会有误。少数反对的主教提前离开。',
    who: ['教宗庇护九世'] },
  { y: 1869, mo: 12.5, t: '《战争与和平》', p: '亚斯纳亚—波利亚纳', m: '今俄罗斯图拉州', ll: [37.53, 54.07], k: 'cul', refs: ['战争与和平'],
    d: '列夫·托尔斯泰在庄园里写了六年，这一年《战争与和平》全部出齐，以几个贵族家庭的命运贯穿 1805 年至 1812 年的对法战争。小说以彼得堡沙龙女主人的一句法语开头：“**唉，公爵，热那亚与卢卡如今只是波拿巴家的领地了。||Well, Prince, so Genoa and Lucca are now just family estates of the Buonapartes.**”',
    who: ['列夫·托尔斯泰'] },
  { y: 1870, mo: 7, t: '埃姆斯电报', p: '埃姆斯', m: '今德国莱茵兰—普法尔茨州巴特埃姆斯', ll: [7.72, 50.33], k: 'dip', refs: ['后世文献'],
    d: '西班牙临时政府请霍亨索伦家族的利奥波德亲王为国王，法兰西强烈反对，亲王撤回了接受。法国大使又在温泉城埃姆斯要求威廉一世保证今后永不再提，被国王婉拒。七月十三日，俾斯麦把国王发来的电报删节后公布，语气显得国王断然拒绝了大使。十九日法兰西对普鲁士宣战，南德诸邦按盟约参战。',
    who: ['奥托·冯·俾斯麦', '威廉一世', '路易—拿破仑·波拿巴'] },
  { y: 1870, mo: 9, t: '色当之战', p: '色当', m: '今法国阿登省', ll: [4.94, 49.7], k: 'war', refs: ['后世文献'],
    d: '八月，巴赞元帅的主力被围在梅斯。麦克马洪率军前往解围，九月一日在色当被毛奇的德军包围，次日拿破仑三世与八万多人投降。消息传到巴黎，九月四日民众涌入立法院，甘必大等人在市政厅宣布成立共和国，组成国防政府，第二帝国覆灭。',
    who: ['路易—拿破仑·波拿巴', '赫尔穆特·冯·毛奇', '莱昂·甘必大'] },
  { y: 1870, mo: 9.5, t: '罗马并入意大利', p: '罗马', m: '今意大利首都', ll: [12.5, 41.91], k: 'war', refs: ['后世文献'],
    d: '普法战争爆发后，保护罗马的法军撤回本国。九月二十日，意大利军队在庇亚门附近轰开城墙，攻入罗马，教宗庇护九世命令守军停止抵抗，此后自称“梵蒂冈的囚徒”。公民投票后罗马并入意大利，次年成为首都。',
    who: ['教宗庇护九世', '维托里奥·埃马努埃莱二世'] },
  { y: 1870, mo: 10, t: '巴黎之围', p: '巴黎', m: '今法国首都', ll: [2.35, 48.86], k: 'war', refs: ['后世文献'],
    d: '九月十九日，德军包围巴黎。十月七日，甘必大乘气球飞出巴黎，到图尔组织新的军队，但无法解围。城中的居民吃完了马肉，又吃动物园的动物，靠气球与信鸽与外界联系。十月底，巴赞率十几万人在梅斯投降。',
    who: ['莱昂·甘必大'] },
  { y: 1871, mo: 1, t: '德意志帝国', p: '凡尔赛', m: '今法国伊夫林省', ll: [2.12, 48.8], k: 'pol', refs: ['后世文献'],
    d: '南德诸邦经谈判加入北德意志邦联。一月十八日，在凡尔赛宫的镜厅，德意志诸侯拥立普鲁士国王威廉一世为德意志皇帝，德意志帝国成立，俾斯麦任帝国首相。二十八日巴黎签订停战协定。同月，萨伏依家族的阿马德奥一世到马德里即位为西班牙国王，他的支持者普里姆已于去年底遇刺身亡。',
    who: ['威廉一世', '奥托·冯·俾斯麦', '赫尔穆特·冯·毛奇', '胡安·普里姆'], post: ['胡安·普里姆'] },
  { y: 1871, mo: 3, t: '巴黎公社', p: '巴黎', m: '今法国首都', ll: [2.36, 48.87], k: 'war', refs: ['后世文献'],
    d: '二月选出的国民议会以保守的君主派居多，梯也尔任行政首脑。三月十八日，政府军想收走蒙马特高地的国民自卫军大炮，引发起义，梯也尔政府撤往凡尔赛。二十八日巴黎公社宣告成立，宣布政教分离，废除面包坊夜工。',
    who: ['阿道夫·梯也尔'] },
  { y: 1871, mo: 5, t: '法兰克福和约与流血周', p: '法兰克福', m: '今德国黑森州', ll: [8.68, 50.11], k: 'dip', refs: ['后世文献'],
    d: '五月十日签订的法兰克福和约中，法兰西把阿尔萨斯与洛林东北部割让给德意志帝国，赔款五十亿法郎。二十一日，凡尔赛军攻进巴黎，经过一个星期的巷战，公社失败，被处决或在战斗中死亡的约有一两万人，杜伊勒里宫与市政厅在大火中被毁。',
    who: ['阿道夫·梯也尔', '奥托·冯·俾斯麦', '威廉一世'] },
];
const PEOPLE_RAW = [
  ['乔治—欧仁·奥斯曼', 'franks', 'Georges-Eugène Haussmann', '1809–1891', '巴黎的新教徒家庭出身，祖父是国民公会议员，外祖父是拿破仑的将军。他学习法律，在外省历任专区区长与省长，以干练强硬著称。1853 年任塞纳省省长，主持改造巴黎十七年，因开支巨大、账目不清受到抨击，1870 年初被解职。'],
  ['居斯塔夫·福楼拜', 'franks', 'Gustave Flaubert', '1821–1880', '鲁昂医院院长之子，在巴黎学法律时癫痫发作，此后住在鲁昂附近的克鲁瓦塞，专心写作。他推敲字句极为严格，写《包法利夫人》用了将近五年，后来又写了以迦太基为背景的《萨朗波》与《情感教育》。'],
  ['夏尔·波德莱尔', 'franks', 'Charles Baudelaire', '1821–1867', '巴黎人，六岁丧父，母亲改嫁军官，他与继父不和，挥霍遗产后被家人指定监护人管理财产。他写艺术评论，翻译爱伦·坡的小说，1857 年出版诗集《恶之花》，描写城市的颓废与忧郁，被视为现代诗歌的先驱。'],
  ['爱德华·马奈', 'franks', 'Édouard Manet', '1832–1883', '巴黎司法官员之子，两次报考海军学校失败后学画，临摹卢浮宫中委拉斯开兹与提香的作品。他以平涂的色块与日常题材画现代生活，《草地上的午餐》与《奥林匹亚》引起轩然大波，被年轻的印象派画家奉为先导。'],
  ['路易·巴斯德', 'franks', 'Louis Pasteur', '1822–1895', '汝拉省多勒的皮革匠之子，在巴黎高等师范学院学化学，发现了酒石酸的旋光异构。他在里尔任教时研究发酵，证明发酵由微生物引起，发明了低温灭菌法，后来研究蚕病、炭疽与狂犬病，研制疫苗。'],
  ['费迪南·德·雷赛布', 'franks', 'Ferdinand de Lesseps', '1805–1894', '外交官世家出身，长年在埃及、西班牙等地任领事与公使，与埃及王子赛义德自幼相识。1854 年赛义德继任埃及总督后，授予他开凿苏伊士地峡的特许，他筹资组建运河公司，主持施工十年。'],
  ['莱昂·甘必大', 'franks', 'Léon Gambetta', '1838–1882', '卡奥尔杂货商之子，祖上是热那亚人，童年一只眼失明。他在巴黎当律师，1868 年在一桩政治案件的辩护中抨击第二帝国而成名，次年当选议员。1870 年九月参与宣布共和，任内政部长，乘气球飞出被围的巴黎，在外省组织抵抗。'],
  ['阿道夫·梯也尔', 'franks', 'Adolphe Thiers', '1797–1877', '马赛人，当过记者，写了十卷本《法国革命史》。七月王朝时两度任首相，1851 年政变时被捕放逐，后来回国当选议员，1870 年反对对普鲁士宣战。1871 年二月被国民议会推为行政首脑，与德意志议和，镇压巴黎公社，八月任共和国总统。'],
  ['维克多·雨果', 'franks', '', '', ''],
  ['路易—拿破仑·波拿巴', 'franks', '', '', ''],
  ['弗洛伦丝·南丁格尔', 'anjou', 'Florence Nightingale', '1820–1910', '富有的英国家庭出身，生于佛罗伦萨，以城名命名。她不顾家人反对学习护理，在德意志的凯撒斯韦特接受训练。克里米亚战争后她用统计数据推动军队医疗改革，1860 年在伦敦圣托马斯医院创办护士学校，奠定了近代护理专业。'],
  ['阿尔弗雷德·丁尼生', 'anjou', 'Alfred Tennyson', '1809–1892', '林肯郡乡村牧师之子，在剑桥读书时加入“使徒社”。好友哈勒姆早逝，他写了十七年的组诗《悼念》，1850 年出版，同年继华兹华斯任桂冠诗人。他的诗作还有《尤利西斯》《轻骑兵冲锋》与以亚瑟王传说为题材的《国王叙事诗》。'],
  ['约翰·斯图尔特·密尔', 'anjou', 'John Stuart Mill', '1806–1873', '功利主义学者詹姆斯·密尔之子，三岁学希腊文，八岁学拉丁文，受父亲与边沁的严格教育，二十岁时陷入精神危机。他在东印度公司任职三十多年，著有《逻辑体系》《政治经济学原理》《论自由》与《妇女的屈从地位》，1865 年当选议员，提出妇女选举权的议案。'],
  ['本杰明·迪斯雷利', 'anjou', '', '', ''],
  ['威廉·格莱斯顿', 'anjou', '', '', ''],
  ['亚伯拉罕·林肯', 'usa', 'Abraham Lincoln', '1809–1865', '生于肯塔基的木屋，在印第安纳与伊利诺伊的边疆长大，几乎没有上过学，靠自学当上律师。他做过一任国会议员，1858 年竞选参议员时与道格拉斯辩论奴隶制而闻名，1860 年当选总统，领导联邦打赢内战，1865 年四月遇刺身亡。'],
  ['哈丽雅特·比彻·斯托', 'usa', 'Harriet Beecher Stowe', '1811–1896', '康涅狄格州著名牧师莱曼·比彻之女，在辛辛那提住了十八年，隔河就是蓄奴的肯塔基州，接触到逃亡的奴隶。1850 年逃亡奴隶法通过后，她写成《汤姆叔叔的小屋》，此后三次访问英国，受到废奴团体的热烈欢迎。'],
  ['罗伯特·李', 'usa', 'Robert E. Lee', '1807–1870', '弗吉尼亚名门出身，父亲是独立战争的骑兵将领。他以第二名毕业于西点军校，在美墨战争中立功，任过西点军校校长。内战爆发时他拒绝了北军的统帅职位，随弗吉尼亚加入南方，统率北弗吉尼亚军团，1865 年投降，战后任华盛顿学院院长。'],
  ['尤利西斯·格兰特', 'usa', 'Ulysses S. Grant', '1822–1885', '俄亥俄的皮革匠之子，毕业于西点军校，参加过美墨战争，1854 年退伍，经商屡屡失败。内战中他攻下多纳尔逊堡与维克斯堡，1864 年任北军总司令，次年接受李的投降，1869 年起任两届美国总统。'],
  ['刘易斯·卡罗尔', 'anjou', 'Lewis Carroll', '1832–1898', '本名查尔斯·勒特威奇·道奇森，柴郡牧师之子，在牛津基督堂学院读书，此后在学院任数学讲师近三十年，终身未婚。他口吃，喜爱摄影与文字游戏，1865 年出版《爱丽丝漫游奇境》，1871 年出版续集《爱丽丝镜中奇遇》。'],
  ['弗雷德里克·道格拉斯', 'usa', '', '', ''],
  ['查尔斯·狄更斯', 'anjou', '', '', ''],
  ['查尔斯·达尔文', 'anjou', '', '', ''],
  ['维多利亚女王', 'anjou', '', '', ''],
  ['奥托·冯·俾斯麦', 'prussia', '', '', ''],
  ['威廉一世', 'prussia', '', '', ''],
  ['赫尔穆特·冯·毛奇', 'prussia', 'Helmuth von Moltke', '1800–1891', '梅克伦堡的贵族之子，先在丹麦军中服役，后转入普鲁士军队，在奥斯曼帝国当过四年军事顾问。1857 年任普鲁士总参谋长，重视铁路运输、电报通信与参谋作业，指挥了对丹麦、奥地利与法兰西的战争，被称为“老毛奇”。他寡言少语，以“沉默者”闻名。'],
  ['理查德·瓦格纳', 'prussia', '', '', ''],
  ['卡尔·马克思', 'prussia', '', '', ''],
  ['弗里德里希·恩格斯', 'prussia', '', '', ''],
  ['腓特烈·威廉四世', 'prussia', '', '', ''],
  ['戴阿克·费伦茨', 'eastfr', 'Ferenc Deák', '1803–1876', '匈牙利佐洛州的地主，律师出身，1848 年任匈牙利政府的司法部长，反对与奥地利决裂，没有参加独立战争。此后他以消极抵抗坚持 1848 年的四月法令，被称为“国家的智者”，1867 年促成奥匈妥协，本人拒绝出任首相。'],
  ['安德拉希·久洛', 'eastfr', '', '', ''],
  ['格雷戈尔·孟德尔', 'eastfr', 'Gregor Mendel', '1822–1884', '西里西亚农民之子，家境贫寒，1843 年进入布尔诺的奥古斯丁修道院，后来到维也纳大学学习物理、数学与植物学，回修道院任教。他用豌豆做了多年杂交实验，1866 年发表论文，1868 年当选修道院院长，此后很少再做研究。他的定律在 1900 年才被重新发现。'],
  ['弗朗茨·约瑟夫', 'eastfr', '', '', ''],
  ['卡米洛·加富尔', 'savoy', 'Camillo Benso di Cavour', '1810–1861', '皮埃蒙特侯爵之子，生于都灵，在军事学院读书，当过工兵军官，后来经营家族庄园，推广新式农业，游历英法，研究议会政治与经济。1847 年创办报纸《复兴报》，1852 年任撒丁首相，借法兰西之力统一了意大利北部与中部，1861 年意大利王国成立后不久去世。'],
  ['朱塞佩·威尔第', 'savoy', 'Giuseppe Verdi', '1813–1901', '帕尔马公国布塞托附近的旅店主之子，报考米兰音乐学院未被录取，跟私人老师学习。1842 年歌剧《纳布科》成功，此后写了《弄臣》《游吟诗人》《茶花女》《阿依达》等，他的名字被当作“意大利国王维托里奥·埃马努埃莱”的缩写口号，1861 年当选意大利议会议员。'],
  ['朱塞佩·加里波第', 'savoy', '', '', ''],
  ['维托里奥·埃马努埃莱二世', 'savoy', '', '', ''],
  ['沙皇亚历山大二世', 'vladimir', '', '', ''],
  ['列夫·托尔斯泰', 'vladimir', '', '', ''],
  ['费奥多尔·陀思妥耶夫斯基', 'vladimir', 'Fyodor Dostoevsky', '1821–1881', '莫斯科一家贫民医院的医生之子，在军事工程学校读书。1846 年发表《穷人》成名，1849 年因参加彼得拉舍夫斯基小组被捕，临刑前被改判在西伯利亚服苦役四年，后又当兵数年。他患有癫痫，嗜赌，后来写了《罪与罚》《白痴》与《卡拉马佐夫兄弟》。'],
  ['德米特里·门捷列夫', 'vladimir', 'Dmitri Mendeleev', '1834–1907', '西伯利亚托博尔斯克中学校长的幼子，父亲早逝，母亲带他到圣彼得堡求学。他在海德堡进修，1867 年任圣彼得堡大学化学教授，1869 年提出元素周期律，后来还研究石油、气体与度量衡，任俄罗斯度量衡局局长。'],
  ['伊玛目沙米勒', 'vladimir', 'Imam Shamil', '1797–1871', '达吉斯坦的阿瓦尔人，学习伊斯兰教法与阿拉伯语，追随苏非派导师。1834 年被推为第三任伊玛目，在达吉斯坦与车臣建立以教法治理的政权，与俄军周旋二十五年。1859 年投降后被软禁在卡卢加，晚年获准朝觐，死于麦地那。'],
  ['尼古拉一世', 'vladimir', '', '', ''],
  ['阿卜杜勒阿齐兹', 'ottomans', '', '', ''],
  ['阿卜杜勒迈吉德一世', 'ottomans', '', '', ''],
  ['伊斯梅尔帕夏', 'egypt', '', '', ''],
  ['胡安·普里姆', 'castile', 'Juan Prim', '1814–1870', '加泰罗尼亚雷乌斯人，在第一次卡洛斯战争中从士兵升为军官，1860 年在摩洛哥战争中立功，受封为侯爵。他多次策划起事，1868 年领导推翻伊莎贝拉二世的革命，任首相兼陆军大臣，为西班牙寻找新国王。1870 年十二月在马德里遇刺，三天后去世。'],
  ['伊莎贝拉二世', 'castile', '', '', ''],
  ['克里斯蒂安九世', 'denmark', 'Christian IX', '1818–1906', '石勒苏益格—荷尔斯泰因—松德堡—格吕克斯堡家族的王子，1852 年的伦敦议定书指定他为无嗣的腓特烈七世的继承人。1863 年即位后不久就在战争中失去三公国。他的子女分别成为英国王后、俄国皇后与希腊国王，被称为“欧洲的岳父”。'],
  ['希腊国王奥托', 'greece', 'Otto of Greece', '1815–1867', '巴伐利亚国王路德维希一世的次子，1832 年由列强选为希腊第一任国王，次年十七岁时到纳夫普利翁即位，由巴伐利亚摄政团辅政。1843 年雅典起义迫使他颁布宪法。他没有子女，1862 年被废后回到巴伐利亚。'],
  ['希腊国王乔治一世', 'greece', '', '', ''],
  ['比利时的利奥波德二世', 'belgium', '', '', ''],
  ['比利时的利奥波德一世', 'belgium', '', '', ''],
  ['亚历山德鲁·约安·库扎', 'romania', 'Alexandru Ioan Cuza', '1820–1873', '摩尔达维亚的小贵族，在巴黎读书，参加 1848 年雅西的革命运动。1859 年同时当选摩尔达维亚与瓦拉几亚两公国的大公，推行土地改革、没收修道院地产、颁布民法与免费初等教育，1866 年被迫退位，死于海德堡。'],
  ['卡罗尔一世', 'romania', '', '', ''],
  ['亨利·杜南', 'swiss', 'Henry Dunant', '1828–1910', '日内瓦的富商之子，笃信加尔文宗，在阿尔及利亚经营农场与磨坊。1859 年他到意大利求见拿破仑三世，路过索尔费里诺战场，组织救护伤员，1862 年出版《索尔费里诺回忆》，促成红十字会与日内瓦公约，后来破产，晚年贫病，1901 年获得首届诺贝尔和平奖。'],
  ['阿尔弗雷德·诺贝尔', 'svear', 'Alfred Nobel', '1833–1896', '斯德哥尔摩发明家之子，童年随父亲到圣彼得堡，父亲在那里制造水雷。他在欧美各地学习化学，研究如何安全使用硝化甘油，1867 年发明达纳炸药，后来在欧洲各国开设工厂，还投资巴库的石油，遗嘱以遗产设立诺贝尔奖。'],
  ['教宗庇护九世', 'papacy', '', '', ''],
  ['纳赛尔丁沙', 'safavid', 'Naser al-Din Shah Qajar', '1831–1896', '穆罕默德沙之子，1848 年十六岁即位，任用埃米尔·卡比尔改革，后来又将他处死。他在位将近五十年，三次出访欧洲，喜爱摄影，留下了旅行日记，1896 年在雷伊的圣陵被刺身亡。'],
  ['奥斯卡一世', 'svear', '', '', ''],
];
